-- Migration: 008_budget_approval.sql
-- Apply once after 007. Existing activities remain authorised at their current budgets.
begin;
create table public.budget_requests (
 id uuid primary key default gen_random_uuid(),
 activity_id uuid references public.activities(id),
 name text not null, description text, event_date date,
 base_budget numeric(12,2), proposed_budget numeric(12,2) not null check(proposed_budget>=0),
 reason text not null, requested_by uuid not null references public.profiles(id),
 status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')),
 reviewed_by uuid references public.profiles(id), review_note text,
 created_at timestamptz not null default now(), reviewed_at timestamptz
);
create unique index budget_one_pending on public.budget_requests(activity_id) where status='pending';
alter table public.budget_requests enable row level security;
revoke all on public.budget_requests from anon,authenticated;
-- No direct browser writes/reads. Dedicated role-checked endpoints below.

-- Replace the old direct-write endpoint so old clients cannot bypass approval.
create or replace function public.ml_save_activity(p_activity_id uuid,p_name text,p_description text,p_budget numeric,p_event_date date,p_reason text)
returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); a public.activities; result uuid; spent numeric;
begin
 if not public.ml_is_treasurer() then raise exception 'Treasurer access required.'; end if;
 if p_name is null or length(trim(p_name)) not between 1 and 120 then raise exception 'Activity name must contain 1 to 120 characters.'; end if;
 if p_budget is null or p_budget<0 or p_budget>9999999999.99 or p_budget<>round(p_budget,2) then raise exception 'Enter a valid budget with at most two decimal places.'; end if;
 if length(coalesce(p_description,''))>2000 then raise exception 'Activity description is too long.'; end if;
 if p_reason is null or length(trim(p_reason)) not between 3 and 1000 then raise exception 'Provide a request reason of 3 to 1000 characters.'; end if;
 if p_activity_id is not null then
  select * into a from public.activities where id=p_activity_id for update;
  if not found or a.status<>'active' then raise exception 'Only active activities can be updated.'; end if;
  if exists(select 1 from public.budget_requests where activity_id=a.id and status='pending') then raise exception 'This activity already has a pending budget request.'; end if;
  select coalesce(sum(amount),0) into spent from public.claims where activity_id=a.id and status in ('approved','paid');
  if p_budget<spent then raise exception 'Budget cannot be lower than approved expenditure.'; end if;
 end if;
 insert into public.budget_requests(activity_id,name,description,event_date,base_budget,proposed_budget,reason,requested_by)
 values(p_activity_id,trim(p_name),trim(p_description),p_event_date,a.budget,p_budget,trim(p_reason),u) returning id into result;
 return result;
end; $$;

create function public.ml_list_budget_requests() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform public.ml_require_user();
 if not exists(select 1 from public.profiles where id=auth.uid() and role in ('president','treasurer')) then raise exception 'President or Treasurer access required.'; end if;
 return (select coalesce(jsonb_agg(to_jsonb(s) order by s.created_at desc,s.id),'[]'::jsonb)
 from (select r.*,p.display_name as requester_name,v.display_name as reviewer_name
 from public.budget_requests r join public.profiles p on p.id=r.requested_by
 left join public.profiles v on v.id=r.reviewed_by
 order by (r.status='pending') desc,r.created_at desc,r.id
 limit 500) s);
end; $$;

create function public.ml_decide_budget(p_request_id uuid,p_approve boolean,p_note text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); r public.budget_requests; a public.activities; aid uuid; spent numeric;
begin
 if not exists(select 1 from public.profiles where id=u and role='president') then raise exception 'President access required.'; end if;
 if p_approve is null then raise exception 'Select a decision.'; end if;
 if length(coalesce(p_note,''))>1000 or (not p_approve and length(trim(coalesce(p_note,'')))<3) then raise exception 'Rejection requires a reason of 3 to 1000 characters.'; end if;
 select activity_id into aid from public.budget_requests where id=p_request_id;
 -- Same activity-first locking order as claim approval and payment.
 if aid is not null then select * into a from public.activities where id=aid for update; end if;
 select * into r from public.budget_requests where id=p_request_id for update;
 if not found or r.status<>'pending' then raise exception 'Request is no longer pending.'; end if;
 if r.requested_by=u then raise exception 'You cannot approve or reject your own request.'; end if;
 if p_approve then
  if r.activity_id is null then
   insert into public.activities(name,description,event_date,budget,created_by)
   values(r.name,r.description,r.event_date,r.proposed_budget,r.requested_by) returning id into aid;
  else
   if a.status<>'active' then raise exception 'Activity is closed. Reject this request or reopen the activity first.'; end if;
   if a.budget<>r.base_budget then raise exception 'Budget changed since submission. Reject and request a fresh proposal.'; end if;
   select coalesce(sum(amount),0) into spent from public.claims where activity_id=aid and status in ('approved','paid');
   if r.proposed_budget<spent then raise exception 'Budget cannot be lower than approved expenditure. Reject and request a higher budget.'; end if;
   update public.activities set name=r.name,description=r.description,event_date=r.event_date,budget=r.proposed_budget,updated_at=now() where id=aid;
  end if;
  insert into public.activity_events(activity_id,actor_id,old_budget,new_budget,note)
  values(aid,u,r.base_budget,r.proposed_budget,'Budget approved: '||r.reason||case when nullif(trim(p_note),'') is not null then ' / '||trim(p_note) else '' end);
 end if;
 update public.budget_requests set status=case when p_approve then 'approved' else 'rejected' end,
 activity_id=case when p_approve then aid else activity_id end,reviewed_by=u,review_note=trim(coalesce(p_note,'')),reviewed_at=now() where id=r.id;
end; $$;

create function public.ml_cancel_budget(p_request_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); r public.budget_requests; aid uuid;
begin
 if not public.ml_is_treasurer() then raise exception 'Treasurer access required.'; end if;
 select activity_id into aid from public.budget_requests where id=p_request_id;
 if aid is not null then perform 1 from public.activities where id=aid for update; end if;
 select * into r from public.budget_requests where id=p_request_id for update;
 if not found or r.status<>'pending' or r.requested_by<>u then raise exception 'Only your own pending request can be cancelled.'; end if;
 update public.budget_requests set status='cancelled',review_note='Withdrawn by requester.',reviewed_at=now() where id=r.id;
end; $$;
revoke all on function public.ml_list_budget_requests(), public.ml_decide_budget(uuid,boolean,text), public.ml_cancel_budget(uuid) from public,anon,authenticated;
grant execute on function public.ml_list_budget_requests(), public.ml_decide_budget(uuid,boolean,text), public.ml_cancel_budget(uuid) to authenticated;
commit;

-- Migration: 009_ai_claim_check.sql
-- Run once after 008. AI reports are advisory and never change claim status.
begin;
create table public.ai_claim_checks (
 id uuid primary key default gen_random_uuid(),
 claim_id uuid references public.claims(id) on delete set null,
 requested_by uuid not null references public.profiles(id),
 input_signature text not null,
 status text not null default 'running' check(status in ('running','complete','failed')),
 result jsonb, model text not null,
 created_at timestamptz not null default now(), finished_at timestamptz
);
create index on public.ai_claim_checks(claim_id,created_at desc);
create index on public.ai_claim_checks(requested_by,created_at desc);
alter table public.ai_claim_checks enable row level security;
revoke all on public.ai_claim_checks from anon,authenticated;
grant select on public.ai_claim_checks to authenticated;
grant all on public.ai_claim_checks to service_role;
create policy ai_check_read on public.ai_claim_checks for select to authenticated
using(exists(select 1 from public.claims c where c.id=claim_id and (c.claimant_id=auth.uid() or public.ml_is_treasurer())));

-- Called ONLY by the server after validating the real user's session.
create function public.ml_begin_ai_check(p_user uuid,p_claim uuid,p_signature text,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
declare c public.claims; rid uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('moneylai-ai-user-'||p_user::text,0));
 select * into c from public.claims where id=p_claim for update;
 if not found or not (c.claimant_id=p_user or exists(select 1 from public.profiles where id=p_user and role='treasurer')) then
  raise exception 'Claim access denied.';
 end if;
 if c.status not in ('draft','submitted','rejected') then raise exception 'AI checks are available before approval.'; end if;
 if exists(select 1 from public.ai_claim_checks where claim_id=p_claim and status='running' and created_at>now()-interval '3 minutes') then
  raise exception 'A check is already running. Please wait a few minutes.';
 end if;
 if exists(select 1 from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '30 seconds') then
  raise exception 'Please wait 30 seconds before another check.';
 end if;
 if (select count(*) from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '24 hours')>=20 then
  raise exception 'Daily AI check limit reached (20 checks per user).';
 end if;
 update public.ai_claim_checks set status='failed',finished_at=now() where claim_id=p_claim and status='running';
 insert into public.ai_claim_checks(claim_id,requested_by,input_signature,model) values(p_claim,p_user,p_signature,p_model) returning id into rid;
 return rid;
end; $$;
revoke all on function public.ml_begin_ai_check(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.ml_begin_ai_check(uuid,uuid,text,text) to service_role;
commit;

-- Migration: 010_claim_coaching.sql
-- Apply once after 009. Existing claims and audit records are preserved.
begin;
alter table public.claims drop constraint claims_status_check;
alter table public.claims add constraint claims_status_check check(status in ('draft','submitted','needs_info','approved','rejected','paid'));
alter table public.claims add column info_requested_at timestamptz;
create table public.claim_clarifications (
 id uuid primary key default gen_random_uuid(),
 claim_id uuid not null references public.claims(id) on delete cascade,
 requested_by uuid not null references public.profiles(id),
 question text not null check(length(trim(question)) between 3 and 1000),
 reply text check(length(trim(reply)) between 3 and 2000),
 requested_at timestamptz not null default now(), responded_at timestamptz
);
create unique index clarification_one_open on public.claim_clarifications(claim_id) where responded_at is null;
alter table public.claim_clarifications enable row level security;
revoke all on public.claim_clarifications from anon,authenticated;
grant select on public.claim_clarifications to authenticated;
create policy clarification_read on public.claim_clarifications for select to authenticated using(exists(
 select 1 from public.claims c where c.id=claim_id and (c.claimant_id=auth.uid() or public.ml_is_treasurer())));

create function public.ml_request_information(p_claim_id uuid,p_question text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); c public.claims;
begin
 if not public.ml_is_treasurer() then raise exception 'Treasurer access required.'; end if;
 c:=public.ml_lock_claim(p_claim_id);
 if c.claimant_id=u or c.status<>'submitted' then raise exception 'Only another member''s submitted claim can be queried.'; end if;
 if p_question is null or length(trim(p_question)) not between 3 and 1000 then raise exception 'Explain what is missing in 3 to 1000 characters.'; end if;
 insert into public.claim_clarifications(claim_id,requested_by,question) values(c.id,u,trim(p_question));
 update public.claims set status='needs_info',info_requested_at=now(),updated_at=now() where id=c.id;
 perform public.ml_event(c.id,'information_requested',trim(p_question));
end; $$;

create or replace function public.ml_return_to_draft(p_claim_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); c public.claims;
begin
 c:=public.ml_lock_claim(p_claim_id);
 if c.claimant_id<>u or c.status not in ('submitted','rejected','needs_info') then raise exception 'This claim cannot be returned to draft.'; end if;
 update public.claims set status='draft',updated_at=now() where id=c.id;
 perform public.ml_event(c.id,case when c.status='needs_info' then 'information_response_started' when c.status='rejected' then 'revision_started' else 'withdrawn' end,'Returned to draft.');
end; $$;

-- Guard the existing submit RPC too: users cannot bypass a requested reply.
create function public.ml_check_information_reply() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.status='submitted' and exists(select 1 from public.claim_clarifications where claim_id=new.id and responded_at is null) then
  raise exception 'Reply to the Treasurer''s request before resubmitting.';
 end if;
 return new;
end; $$;
create trigger claim_information_reply before update of status on public.claims for each row execute function public.ml_check_information_reply();
create function public.ml_reply_information(p_claim_id uuid,p_reply text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); c public.claims;
begin
 c:=public.ml_lock_claim(p_claim_id);
 if c.claimant_id<>u or c.status<>'draft' then raise exception 'Prepare your own draft before replying.'; end if;
 if p_reply is null or length(trim(p_reply)) not between 3 and 2000 then raise exception 'Explain your changes in 3 to 2000 characters.'; end if;
 update public.claim_clarifications set reply=trim(p_reply),responded_at=now() where claim_id=c.id and responded_at is null;
 if not found then raise exception 'No outstanding request.'; end if;
 perform public.ml_submit_claim(c.id);
 update public.claims set info_requested_at=null where id=c.id;
 perform public.ml_event(c.id,'information_supplied',trim(p_reply));
end; $$;

alter function public.ml_set_activity_status(uuid,text,text) rename to ml_set_activity_status_before_information;
revoke all on function public.ml_set_activity_status_before_information(uuid,text,text) from public,anon,authenticated;
create function public.ml_set_activity_status(p_activity_id uuid,p_status text,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not public.ml_is_treasurer() then raise exception 'Treasurer access required.'; end if;
 perform 1 from public.activities where id=p_activity_id for update;
 if p_status='closed' and exists(select 1 from public.claims where activity_id=p_activity_id and info_requested_at is not null) then raise exception 'Resolve outstanding information requests before closing.'; end if;
 perform public.ml_set_activity_status_before_information(p_activity_id,p_status,p_reason);
end; $$;

-- Fingerprints are server-generated; no browser reads or writes to this index.
create table public.receipt_fingerprints (
 attachment_id uuid primary key references public.attachments(id) on delete cascade,
 sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$'),
 merchant text, amount numeric(12,2), currency text, purchase_date date,
 receipt_number text, indexed_at timestamptz not null default now()
);
create index on public.receipt_fingerprints(sha256);
alter table public.receipt_fingerprints enable row level security;
revoke all on public.receipt_fingerprints from public,anon,authenticated;
grant all on public.receipt_fingerprints to service_role;
create function public.ml_receipt_duplicates(p_claim_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform public.ml_require_user();
 if not public.ml_is_treasurer() then raise exception 'Treasurer access required.'; end if;
 return (select coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) from (
  select distinct c.id as claim_id,c.status,c.amount,a.original_name as current_file,b.original_name as matched_file,
   case when x.sha256=y.sha256 then 'identical_file' else 'matching_receipt_details' end as basis,
   y.merchant,y.purchase_date,y.amount as receipt_amount,y.receipt_number
  from public.attachments a join public.receipt_fingerprints x on x.attachment_id=a.id
  join public.receipt_fingerprints y on y.attachment_id<>x.attachment_id
  join public.attachments b on b.id=y.attachment_id join public.claims c on c.id=b.claim_id
  where a.claim_id=p_claim_id and a.kind='receipt' and b.kind='receipt' and c.id<>p_claim_id and c.status<>'draft'
   and (x.sha256=y.sha256 or (
    x.merchant is not null and nullif(trim(x.merchant),'') is not null and lower(trim(x.merchant))=lower(trim(y.merchant))
    and x.amount=y.amount and x.currency=y.currency and x.purchase_date=y.purchase_date
    and (x.receipt_number is null or y.receipt_number is null or lower(trim(x.receipt_number))=lower(trim(y.receipt_number)))
   ))
  order by c.id limit 30
 ) s);
end; $$;
revoke all on function public.ml_request_information(uuid,text),public.ml_reply_information(uuid,text),public.ml_check_information_reply(),public.ml_set_activity_status(uuid,text,text),public.ml_receipt_duplicates(uuid) from public,anon,authenticated;
grant execute on function public.ml_request_information(uuid,text),public.ml_reply_information(uuid,text),public.ml_set_activity_status(uuid,text,text),public.ml_receipt_duplicates(uuid) to authenticated;
create or replace function public.ml_begin_ai_check(p_user uuid,p_claim uuid,p_signature text,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
declare c public.claims; rid uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('moneylai-ai-user-'||p_user::text,0));
 select * into c from public.claims where id=p_claim for update;
 if not found or not (c.claimant_id=p_user or exists(select 1 from public.profiles where id=p_user and role='treasurer')) then
  raise exception 'Claim access denied.';
 end if;
 if c.status not in ('draft','submitted','needs_info','rejected') then raise exception 'AI checks are available before approval.'; end if;
 if exists(select 1 from public.ai_claim_checks where claim_id=p_claim and status='running' and created_at>now()-interval '3 minutes') then
  raise exception 'A check is already running. Please wait a few minutes.';
 end if;
 if exists(select 1 from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '30 seconds') then
  raise exception 'Please wait 30 seconds before another check.';
 end if;
 if (select count(*) from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '24 hours')>=20 then
  raise exception 'Daily AI check limit reached (20 checks per user).';
 end if;
 update public.ai_claim_checks set status='failed',finished_at=now() where claim_id=p_claim and status='running';
 insert into public.ai_claim_checks(claim_id,requested_by,input_signature,model) values(p_claim,p_user,p_signature,p_model) returning id into rid;
 return rid;
end; $$;

commit;

-- Migration: 012_activity_exports_only.sql
-- Apply after 010, or after the retired 011_procurement_exports.sql.
-- Keeps historical procurement data; disables its endpoints and budget guards.
begin;

drop trigger if exists guard_purchase_activity on public.activities;
drop trigger if exists guard_purchase_claim on public.claims;
do $$
declare f record; t text;
begin
  for f in select p.oid::regprocedure as signature from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and (p.proname like 'ml\_%purchase%' escape '\' or p.proname='ml_activity_budgets')
  loop
    execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  end loop;
  foreach t in array array['purchase_requests','purchase_events'] loop
    if to_regclass('public.'||t) is not null then
      execute format('revoke all on table public.%I from public,anon,authenticated',t);
    end if;
  end loop;
end $$;

-- Restore the original budget model: only approved/paid claims consume budget.
create or replace function public.ml_activity_summary() returns table(
  id uuid,name text,description text,budget numeric,event_date date,status text,
  approved_spend numeric,pending_amount numeric,paid_amount numeric,remaining_budget numeric,unpaid_amount numeric)
language plpgsql stable security definer set search_path='' as $$
begin
  perform public.ml_require_user();
  return query select a.id,a.name,a.description,a.budget,a.event_date,a.status,
    coalesce(s.committed,0),coalesce(s.pending,0),coalesce(s.paid,0),a.budget-coalesce(s.committed,0),coalesce(s.unpaid,0)
  from public.activities a left join lateral (
    select sum(c.amount) filter(where c.status in ('approved','paid')) committed,
      sum(c.amount) filter(where c.status='submitted') pending,
      sum(c.amount) filter(where c.status='paid') paid,
      sum(c.amount) filter(where c.status='approved') unpaid
    from public.claims c where c.activity_id=a.id
  ) s on true order by a.created_at desc;
end; $$;

-- IF NOT EXISTS preserves claim numbers already assigned by old 011.
alter table public.claims add column if not exists claim_number bigint generated always as identity;
create unique index if not exists claims_export_number_unique on public.claims(claim_number);

create or replace function public.ml_activity_export(p_activity_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); fiscal boolean; a jsonb;
begin
  if not exists(select 1 from public.profiles where id=u and role in ('treasurer','president')) then
    raise exception 'Only Treasurer or President can export an activity.';
  end if;
  fiscal:=public.ml_is_treasurer();
  select to_jsonb(s) into a from public.ml_activity_summary() s where s.id=p_activity_id;
  if a is null then raise exception 'Activity not found.'; end if;
  if (select count(*) from public.claims where activity_id=p_activity_id and status<>'draft')>1000 then
    raise exception 'This activity exceeds the export limit of 1000 claims.';
  end if;
  return jsonb_build_object(
    'generated_at',now(),'scope',case when fiscal then 'treasurer_evidence' else 'president_summary' end,
    'activity',a,
    'claims',coalesce((select jsonb_agg(jsonb_build_object(
      'id',c.id,'code','ML-'||lpad(c.claim_number::text,greatest(6,length(c.claim_number::text)),'0'),
      'claimant_name',p.display_name,'amount',c.amount,'description',c.description,
      'status',c.status,'submitted_at',c.submitted_at,'category',c.category,'purchase_date',c.purchase_date
    ) order by c.claim_number) from public.claims c join public.profiles p on p.id=c.claimant_id
      where c.activity_id=p_activity_id and c.status<>'draft'),'[]'::jsonb),
    'attachments',case when fiscal then coalesce((select jsonb_agg(jsonb_build_object(
      'claim_id',x.claim_id,'kind',x.kind,'storage_path',x.storage_path,'original_name',x.original_name,
      'mime_type',x.mime_type,'size_bytes',x.size_bytes) order by x.created_at,x.id)
      from public.attachments x join public.claims c on c.id=x.claim_id
      where c.activity_id=p_activity_id and c.status<>'draft'),'[]'::jsonb) else '[]'::jsonb end,
    'payments',case when fiscal then coalesce((select jsonb_agg(jsonb_build_object(
      'claim_id',x.claim_id,'paid_on',x.paid_on,'reference',x.reference,'amount',x.amount,'proof_path',x.proof_path)
      order by x.created_at,x.id) from public.payments x join public.claims c on c.id=x.claim_id
      where c.activity_id=p_activity_id and c.status<>'draft'),'[]'::jsonb) else '[]'::jsonb end,
    'events',case when fiscal then coalesce((select jsonb_agg(jsonb_build_object(
      'claim_id',x.claim_id,'event_type',x.event_type,'note',x.note,'created_at',x.created_at,'actor',p.display_name)
      order by x.created_at,x.id) from public.claim_events x join public.claims c on c.id=x.claim_id
      join public.profiles p on p.id=x.actor_id
      where c.activity_id=p_activity_id and c.status<>'draft'),'[]'::jsonb) else '[]'::jsonb end,
    'activity_events',case when fiscal then coalesce((select jsonb_agg(jsonb_build_object(
      'old_budget',x.old_budget,'new_budget',x.new_budget,'note',x.note,'created_at',x.created_at,'actor',p.display_name)
      order by x.created_at,x.id) from public.activity_events x join public.profiles p on p.id=x.actor_id
      where x.activity_id=p_activity_id),'[]'::jsonb) else '[]'::jsonb end
  );
end; $$;
revoke all on function public.ml_activity_export(uuid) from public,anon,authenticated;
grant execute on function public.ml_activity_export(uuid) to authenticated;

-- Short-lived download links; files are deleted by the client after downloading.
-- Failed downloads are cleaned on the next export by the same user (after 1 hour).
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('activity-exports','activity-exports',false,62914560,array['application/zip'])
on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists activity_export_upload on storage.objects;
drop policy if exists activity_export_read on storage.objects;
drop policy if exists activity_export_delete on storage.objects;
create policy activity_export_upload on storage.objects for insert to authenticated
with check(bucket_id='activity-exports' and (storage.foldername(name))[1]=auth.uid()::text
  and exists(select 1 from public.profiles where id=auth.uid() and role in ('treasurer','president')));
create policy activity_export_read on storage.objects for select to authenticated
using(bucket_id='activity-exports' and (storage.foldername(name))[1]=auth.uid()::text
  and exists(select 1 from public.profiles where id=auth.uid() and role in ('treasurer','president')));
create policy activity_export_delete on storage.objects for delete to authenticated
using(bucket_id='activity-exports' and (storage.foldername(name))[1]=auth.uid()::text
  and exists(select 1 from public.profiles where id=auth.uid() and role in ('treasurer','president')));
commit;

-- Migration: 013_receipt_assistant.sql
-- Run ONCE after 012. Adds optional single-receipt assistance; no budget changes.
begin;
create table public.receipt_drafts (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id),
 activity_id uuid not null references public.activities(id), claim_id uuid references public.claims(id) on delete set null,
 original_name text not null, mime_type text not null, storage_path text not null unique,
 status text not null default 'pending' check(status in ('pending','running','complete','failed')),
 extraction jsonb, sha256 text, model text, run_id uuid references public.ai_claim_checks(id),
 created_at timestamptz not null default now(), expires_at timestamptz not null default now()+interval '24 hours'
);
create index on public.receipt_drafts(user_id,created_at);
create table public.claim_receipt_plans (
 claim_id uuid primary key references public.claims(id) on delete cascade,
 session_id uuid not null unique references public.receipt_drafts(id),
 attachment_id uuid references public.attachments(id) on delete set null,
 revision integer not null, extraction jsonb not null, selection jsonb not null, calculation jsonb not null,
 sha256 text not null, model text not null, original_name text not null,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.receipt_plan_history (
 id uuid primary key default gen_random_uuid(), claim_id uuid not null references public.claims(id) on delete cascade,
 revision integer not null, actor_id uuid not null references public.profiles(id),
 record jsonb not null, created_at timestamptz not null default now(), unique(claim_id,revision)
);
alter table public.receipt_drafts enable row level security;
alter table public.claim_receipt_plans enable row level security;
alter table public.receipt_plan_history enable row level security;
revoke all on public.receipt_drafts,public.claim_receipt_plans,public.receipt_plan_history from public,anon,authenticated;
grant select on public.receipt_drafts,public.claim_receipt_plans,public.receipt_plan_history to authenticated;
grant all on public.receipt_drafts,public.claim_receipt_plans,public.receipt_plan_history to service_role;
create policy receipt_draft_read on public.receipt_drafts for select to authenticated
using(user_id=auth.uid() or (claim_id is not null and public.ml_is_treasurer()));
create policy receipt_plan_read on public.claim_receipt_plans for select to authenticated
using(exists(select 1 from public.claims c where c.id=claim_id and (c.claimant_id=auth.uid() or public.ml_is_treasurer())));
create policy receipt_plan_history_read on public.receipt_plan_history for select to authenticated
using(exists(select 1 from public.claims c where c.id=claim_id and (c.claimant_id=auth.uid() or public.ml_is_treasurer())));

create function public.ml_create_receipt_draft(p_activity_id uuid,p_name text,p_mime text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); sid uuid:=gen_random_uuid(); path text;
begin
 if not exists(select 1 from public.activities where id=p_activity_id and status='active') then raise exception 'Choose an active activity first.'; end if;
 if p_name is null or length(p_name) not between 1 and 200 or p_mime is null or p_mime not in ('image/jpeg','image/png','application/pdf') then raise exception 'Choose a JPG, PNG or PDF with a name of at most 200 characters.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('moneylai-receipt-upload-'||u::text,0));
 if (select count(*) from public.receipt_drafts where user_id=u and created_at>now()-interval '24 hours')>=40 then raise exception 'Daily receipt upload limit reached. Use manual entry or try tomorrow.'; end if;
 path:=u::text||'/'||sid::text||'/source.'||case p_mime when 'application/pdf' then 'pdf' when 'image/png' then 'png' else 'jpg' end;
 insert into public.receipt_drafts(id,user_id,activity_id,original_name,mime_type,storage_path) values(sid,u,p_activity_id,p_name,p_mime,path);
 return jsonb_build_object('id',sid,'path',path);
end; $$;

-- Shared AI limit with the existing check endpoint. Only the authenticated server may reserve runs.
create function public.ml_begin_receipt_read(p_user uuid,p_session uuid,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
declare s public.receipt_drafts; rid uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('moneylai-ai-user-'||p_user::text,0));
 select * into s from public.receipt_drafts where id=p_session for update;
 if not found or s.user_id<>p_user or s.claim_id is not null or s.expires_at<=now() then raise exception 'Receipt draft is unavailable or expired.'; end if;
 if s.status='complete' then raise exception 'Receipt is already read. Use its saved extraction.'; end if;
 if s.status='running' and exists(select 1 from public.ai_claim_checks where id=s.run_id and created_at>now()-interval '3 minutes') then raise exception 'A receipt reading is already running.'; end if;
 if exists(select 1 from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '30 seconds') then raise exception 'Please wait 30 seconds before another AI request.'; end if;
 if (select count(*) from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '24 hours')>=20 then raise exception 'Daily AI check limit reached (20 checks per user).'; end if;
 insert into public.ai_claim_checks(requested_by,input_signature,model) values(p_user,'receipt:'||s.id::text,p_model) returning id into rid;
 update public.receipt_drafts set status='running',run_id=rid,model=p_model where id=s.id;
 return rid;
end; $$;

-- Returns only own-claim links; other claimants' matches are aggregated, never disclosed.
create function public.ml_receipt_draft_duplicates(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); s public.receipt_drafts; result jsonb;
begin
 select * into s from public.receipt_drafts where id=p_session and user_id=u and status='complete';
 if not found then raise exception 'Receipt reading not found.'; end if;
 select jsonb_build_object('other_matches',count(*) filter(where c.claimant_id<>u),
   'own_matches',coalesce(jsonb_agg(distinct jsonb_build_object('claim_id',c.id,'code','ML-'||lpad(c.claim_number::text,greatest(6,length(c.claim_number::text)),'0'),'status',c.status)) filter(where c.claimant_id=u),'[]'::jsonb)) into result
 from public.receipt_fingerprints f join public.attachments a on a.id=f.attachment_id join public.claims c on c.id=a.claim_id
 where c.status not in ('draft','rejected','cancelled') and c.id is distinct from s.claim_id
 and (f.sha256=s.sha256 or (
   nullif(lower(trim(s.extraction->>'merchant')),'')=lower(trim(f.merchant))
   and f.amount=(s.extraction->>'total')::numeric and f.currency=s.extraction->>'currency'
   and f.purchase_date=(s.extraction->>'date')::date
   and (nullif(trim(s.extraction->>'receipt_number'),'') is null or nullif(trim(f.receipt_number),'') is null or lower(trim(f.receipt_number))=lower(trim(s.extraction->>'receipt_number')))
 ));
 return result;
end; $$;

create function public.ml_prepare_receipt_claim(p_session uuid,p_claim_id uuid,p_amount numeric,p_description text,p_date date,p_category text,p_revision integer) returns uuid
language plpgsql security definer set search_path='' as $$
declare u uuid:=public.ml_require_user(); s public.receipt_drafts; cid uuid; c public.claims;
begin
 -- Serialize session binding, including retries, without reversing the activity/claim lock order.
 perform pg_advisory_xact_lock(hashtextextended('moneylai-receipt-session-'||p_session::text,0));
 select * into s from public.receipt_drafts where id=p_session and user_id=u;
 if not found or s.status<>'complete' or (s.claim_id is null and s.expires_at<=now()) then raise exception 'Receipt draft is unavailable or expired.'; end if;
 cid:=coalesce(s.claim_id,p_claim_id);
 if s.claim_id is not null and p_claim_id is not null and s.claim_id<>p_claim_id then raise exception 'This receipt belongs to another draft.'; end if;
 if cid is null then
   cid:=public.ml_save_claim(null,s.activity_id,p_amount,p_description,p_date,p_category);
 else
   c:=public.ml_lock_claim(cid);
   if c.claimant_id<>u or c.status<>'draft' or c.activity_id<>s.activity_id then raise exception 'Only your matching activity draft can use this receipt.'; end if;
 end if;
 if coalesce((select revision from public.claim_receipt_plans where claim_id=cid),0)<>p_revision then raise exception 'This draft changed in another window. Reload it before saving.'; end if;
 if exists(select 1 from public.attachments a where a.claim_id=cid and a.kind='receipt' and a.storage_path<>u::text||'/'||cid::text||'/'||s.id::text||case s.mime_type when 'application/pdf' then '.pdf' when 'image/png' then '.png' else '.jpg' end) then raise exception 'AI item selection supports one receipt. Remove the existing receipt first, or continue with manual entry.'; end if;
 update public.receipt_drafts set claim_id=cid where id=s.id;
 return cid;
end; $$;

-- Server-only commit: original bytes are verified against sha256 before this RPC.
create function public.ml_finish_receipt_claim(p_user uuid,p_session uuid,p_selection jsonb,p_calculation jsonb,p_fields jsonb,p_revision integer) returns uuid
language plpgsql security definer set search_path='' as $$
declare s public.receipt_drafts; c public.claims; aid uuid; path text; meta jsonb; revision_next integer; amount_value numeric; date_value date;
begin
 select * into s from public.receipt_drafts where id=p_session and user_id=p_user and status='complete';
 if not found or s.claim_id is null then raise exception 'Receipt draft is unavailable.'; end if;
 perform 1 from public.activities where id=s.activity_id and status='active' for update;
 if not found then raise exception 'This activity is closed.'; end if;
 select * into c from public.claims where id=s.claim_id for update;
 if c.claimant_id<>p_user or c.status<>'draft' then raise exception 'Only your own draft can be edited.'; end if;
 if coalesce((select revision from public.claim_receipt_plans where claim_id=c.id),0)<>p_revision then raise exception 'This draft changed in another window. Reload before saving.'; end if;
 amount_value:=(p_fields->>'amount')::numeric; date_value:=(p_fields->>'purchase_date')::date;
 if amount_value is null or amount_value<=0 or amount_value>9999999999.99 or amount_value<>round(amount_value,2) or date_value is null or date_value>(now() at time zone 'Asia/Kuala_Lumpur')::date then raise exception 'Enter a valid claim amount and purchase date.'; end if;
 if length(trim(coalesce(p_fields->>'description',''))) not between 1 and 500 or coalesce(p_fields->>'category','') not in ('Materials','Food & Drinks','Transport','Venue','Equipment','Other') then raise exception 'Enter a valid description and category.'; end if;
 path:=p_user::text||'/'||c.id::text||'/'||s.id::text||case s.mime_type when 'application/pdf' then '.pdf' when 'image/png' then '.png' else '.jpg' end;
 select metadata into meta from storage.objects where bucket_id='receipts' and name=path;
 if not found then raise exception 'Upload the original receipt first.'; end if;
 if exists(select 1 from public.attachments where claim_id=c.id and kind='receipt' and storage_path<>path) then raise exception 'Item selection supports one receipt per claim.'; end if;
 select id into aid from public.attachments where claim_id=c.id and storage_path=path;
 if aid is null then
   if (select count(*) from public.attachments where claim_id=c.id)>=5 then raise exception 'Maximum five attachments per claim.'; end if;
   insert into public.attachments(claim_id,kind,storage_path,original_name,mime_type,size_bytes,uploaded_by)
   values(c.id,'receipt',path,s.original_name,s.mime_type,coalesce((meta->>'size')::bigint,0),p_user) returning id into aid;
 end if;
 revision_next:=p_revision+1;
 insert into public.claim_receipt_plans(claim_id,session_id,attachment_id,revision,extraction,selection,calculation,sha256,model,original_name)
 values(c.id,s.id,aid,revision_next,s.extraction,p_selection,p_calculation,s.sha256,s.model,s.original_name)
 on conflict(claim_id) do update set session_id=excluded.session_id,attachment_id=excluded.attachment_id,revision=excluded.revision,
 extraction=excluded.extraction,selection=excluded.selection,calculation=excluded.calculation,sha256=excluded.sha256,model=excluded.model,original_name=excluded.original_name,updated_at=now();
 update public.claims set amount=amount_value,description=trim(p_fields->>'description'),purchase_date=date_value,category=p_fields->>'category',updated_at=now() where id=c.id;
 insert into public.receipt_plan_history(claim_id,revision,actor_id,record) select c.id,revision_next,p_user,to_jsonb(p) from public.claim_receipt_plans p where p.claim_id=c.id;
 insert into public.claim_events(claim_id,actor_id,event_type,note) values(c.id,p_user,'receipt_selection_saved','Receipt item selection saved (revision '||revision_next||'). Expected RM '||(p_calculation->>'expected_amount')||'; claimed RM '||amount_value||'.');
 insert into public.receipt_fingerprints(attachment_id,sha256,merchant,amount,currency,purchase_date,receipt_number)
 values(aid,s.sha256,s.extraction->>'merchant',(s.extraction->>'total')::numeric,s.extraction->>'currency',(s.extraction->>'date')::date,s.extraction->>'receipt_number')
 on conflict(attachment_id) do update set sha256=excluded.sha256,merchant=excluded.merchant,amount=excluded.amount,currency=excluded.currency,purchase_date=excluded.purchase_date,receipt_number=excluded.receipt_number;
 return c.id;
end; $$;
revoke all on function public.ml_create_receipt_draft(uuid,text,text),public.ml_receipt_draft_duplicates(uuid),public.ml_prepare_receipt_claim(uuid,uuid,numeric,text,date,text,integer),public.ml_begin_receipt_read(uuid,uuid,text),public.ml_finish_receipt_claim(uuid,uuid,jsonb,jsonb,jsonb,integer) from public,anon,authenticated;
grant execute on function public.ml_create_receipt_draft(uuid,text,text),public.ml_receipt_draft_duplicates(uuid),public.ml_prepare_receipt_claim(uuid,uuid,numeric,text,date,text,integer) to authenticated;
grant execute on function public.ml_begin_receipt_read(uuid,uuid,text),public.ml_finish_receipt_claim(uuid,uuid,jsonb,jsonb,jsonb,integer) to service_role;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('receipt-drafts','receipt-drafts',false,5242880,array['image/jpeg','image/png','application/pdf'])
on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy receipt_draft_upload on storage.objects for insert to authenticated
with check(bucket_id='receipt-drafts' and exists(select 1 from public.receipt_drafts s where s.user_id=auth.uid() and s.storage_path=name and s.status='pending' and s.expires_at>now()));
create policy receipt_draft_file_read on storage.objects for select to authenticated
using(bucket_id='receipt-drafts' and exists(select 1 from public.receipt_drafts s where s.user_id=auth.uid() and s.storage_path=name));
create policy receipt_draft_file_delete on storage.objects for delete to authenticated
using(bucket_id='receipt-drafts' and exists(select 1 from public.receipt_drafts s where s.user_id=auth.uid() and s.storage_path=name and s.claim_id is null and (s.status<>'running' or s.expires_at<now())));

-- Preserve summary privacy while adding selection evidence to Treasurer exports.
alter function public.ml_activity_export(uuid) rename to ml_activity_export_before_receipt_assistant;
revoke all on function public.ml_activity_export_before_receipt_assistant(uuid) from public,anon,authenticated;
create function public.ml_activity_export(p_activity_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 result:=public.ml_activity_export_before_receipt_assistant(p_activity_id);
 if public.ml_is_treasurer() then
   result:=result||jsonb_build_object('receipt_plans',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('source_valid',
     (select count(*) from public.attachments a where a.claim_id=p.claim_id and a.kind='receipt')=1 and exists(select 1 from public.attachments a where a.id=p.attachment_id and a.claim_id=p.claim_id and a.kind='receipt')) order by p.claim_id)
     from public.claim_receipt_plans p join public.claims c on c.id=p.claim_id where c.activity_id=p_activity_id and c.status<>'draft'),'[]'::jsonb),
    'receipt_plan_history',coalesce((select jsonb_agg(jsonb_build_object('claim_id',h.claim_id,'revision',h.revision,'created_at',h.created_at,'actor',u.display_name,'record',h.record) order by h.created_at,h.id) from public.receipt_plan_history h join public.claims c on c.id=h.claim_id join public.profiles u on u.id=h.actor_id where c.activity_id=p_activity_id and c.status<>'draft'),'[]'::jsonb));
 end if;
 return result;
end; $$;
revoke all on function public.ml_activity_export(uuid) from public,anon,authenticated;
grant execute on function public.ml_activity_export(uuid) to authenticated;
commit;

-- Migration: 014_member_management.sql
-- Existing projects: run once AFTER 013. Existing accounts and financial records are retained.
-- Also allow your website's /join** redirect in Supabase Auth URL Configuration.
-- Keep {{ .ConfirmationURL }} in Invite/Recovery email templates; configure SMTP for real recipients.
-- Do not rerun SETUP_FRESH.sql or BOOTSTRAP_ROLES.sql on an existing deployment.
begin;

alter table public.profiles add column account_status text not null default 'active'
  check(account_status in ('active','invited','disabled'));
-- New Auth accounts cannot enter the club until an invitation is accepted.
alter table public.profiles alter column account_status set default 'invited';

create function public.ml_account_active(p_user uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles where id=p_user and account_status='active');
$$;
create or replace function public.ml_require_user() returns uuid
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.ml_account_active(auth.uid()) then
   raise exception 'Account is not active. Ask the President about your membership.';
 end if;
 return auth.uid();
end; $$;
create or replace function public.ml_is_treasurer() returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles where id=auth.uid() and role='treasurer' and account_status='active');
$$;
create function public.ml_require_president() returns uuid
language plpgsql stable security definer set search_path='' as $$
declare u uuid:=public.ml_require_user();
begin
 if not exists(select 1 from public.profiles where id=u and role='president') then
   raise exception 'President access required.';
 end if;
 return u;
end; $$;

-- Restrictive policies AND the existing ownership/financial-role policies.
-- An unexpired JWT from a disabled account must not retain direct table/storage access.
do $$ declare t text; begin
 for t in select tablename from pg_tables where schemaname='public' and rowsecurity loop
   execute format('create policy membership_active on public.%I as restrictive for all to authenticated using (public.ml_account_active(auth.uid())) with check (public.ml_account_active(auth.uid()))',t);
 end loop;
end; $$;
-- The account can still read its own minimal profile to display its membership status.
drop policy membership_active on public.profiles;
create policy membership_active on public.profiles as restrictive for select to authenticated
 using(id=auth.uid() or public.ml_account_active(auth.uid()));
create policy membership_active on storage.objects as restrictive for all to authenticated
 using(bucket_id not in ('receipts','payment-proofs','activity-exports','receipt-drafts') or public.ml_account_active(auth.uid()))
 with check(bucket_id not in ('receipts','payment-proofs','activity-exports','receipt-drafts') or public.ml_account_active(auth.uid()));

create table public.member_invitations (
 id uuid primary key default gen_random_uuid(),
 email text not null,
 display_name text not null,
 token uuid not null default gen_random_uuid(),
 status text not null default 'pending' check(status in ('pending','accepted','revoked')),
 created_by uuid not null references public.profiles(id),
 accepted_by uuid references public.profiles(id),
 created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '7 days',
 sent_at timestamptz,
 delivery_status text not null default 'sending' check(delivery_status in ('sending','sent','failed')),
 last_attempt_at timestamptz not null default now(),
 accepted_at timestamptz
);
create unique index member_invitation_pending_email on public.member_invitations(email) where status='pending';
create table public.member_management_events (
 id uuid primary key default gen_random_uuid(),
 actor_id uuid not null references public.profiles(id),
 target_id uuid references public.profiles(id),
 event_type text not null,
 reason text not null,
 details jsonb not null default '{}',
 created_at timestamptz not null default now()
);
create table public.president_handovers (
 id uuid primary key default gen_random_uuid(),
 from_id uuid not null references public.profiles(id),
 to_id uuid not null references public.profiles(id),
 status text not null default 'pending' check(status in ('pending','accepted','cancelled','declined')),
 reason text not null,
 created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '7 days',
 resolved_at timestamptz,
 check(from_id<>to_id)
);
create unique index one_pending_president_handover on public.president_handovers((true)) where status='pending';
alter table public.member_invitations enable row level security;
alter table public.member_management_events enable row level security;
alter table public.president_handovers enable row level security;
revoke all on public.member_invitations,public.member_management_events,public.president_handovers from anon,authenticated;
-- Access is exclusively through narrow RPCs, so invitation tokens and Auth data are never listed.

create function public.ml_members() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform public.ml_require_president();
 return jsonb_build_object(
  'members',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'display_name',p.display_name,
    'email',u.email,'role',p.role,'account_status',p.account_status) order by p.created_at,p.id)
    from public.profiles p join auth.users u on u.id=p.id),'[]'::jsonb),
  'invitations',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'email',i.email,'display_name',i.display_name,
    'status',case when i.status='pending' and i.expires_at<=now() then 'expired' else i.status end,
    'delivery_status',i.delivery_status,'sent_at',i.sent_at,'expires_at',i.expires_at,'created_at',i.created_at)
    order by i.created_at desc) from public.member_invitations i),'[]'::jsonb),
  'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at desc,e.id) from (
    select e.id,e.created_at,e.event_type,e.reason,e.details,a.display_name as actor,t.display_name as target
    from public.member_management_events e join public.profiles a on a.id=e.actor_id
    left join public.profiles t on t.id=e.target_id order by e.created_at desc,e.id limit 100) e),'[]'::jsonb));
end; $$;

create function public.ml_change_member(p_user uuid,p_action text,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid; p public.profiles; next_role text; next_status text;
begin
 perform pg_advisory_xact_lock(714014);
 u:=public.ml_require_president();
 if p_reason is null or length(trim(p_reason)) not between 3 and 500 then raise exception 'Enter a reason of 3 to 500 characters.'; end if;
 select * into p from public.profiles where id=p_user for update;
 if not found then raise exception 'Member not found.'; end if;
 if p.id=u then raise exception 'You cannot change your own role or account status.'; end if;
 if p.role='president' then raise exception 'Use the President handover workflow for a President account.'; end if;
 next_role:=p.role; next_status:=p.account_status;
 if p_action in ('member','treasurer') then
   if p.account_status<>'active' then raise exception 'Only active members can change roles.'; end if;
   next_role:=p_action;
 elsif p_action='disable' then
   if p.account_status<>'active' then raise exception 'Only active members can be disabled.'; end if;
   next_status:='disabled';
 elsif p_action='restore' then
   if p.account_status<>'disabled' then raise exception 'Only disabled members can be restored.'; end if;
   next_status:='active';
 else raise exception 'Invalid member action.';
 end if;
 if next_role=p.role and next_status=p.account_status then raise exception 'This member already has that role.'; end if;
 update public.profiles set role=next_role,account_status=next_status where id=p_user;
 insert into public.member_management_events(actor_id,target_id,event_type,reason,details)
 values(u,p_user,p_action,trim(p_reason),jsonb_build_object('previous_role',p.role,'role',next_role,'previous_status',p.account_status,'status',next_status));
end; $$;

-- Reserve/rotate the app invitation BEFORE contacting Auth. Old app links become invalid immediately.
create function public.ml_prepare_invitation(p_email text,p_name text,p_invitation uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid; i public.member_invitations; target uuid; v_email text:=lower(trim(p_email));
begin
 perform pg_advisory_xact_lock(714014);
 u:=public.ml_require_president();
 if p_invitation is null then
   if v_email is null or length(v_email)>254 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Enter a valid email address.'; end if;
   if p_name is null or length(trim(p_name)) not between 1 and 100 then raise exception 'Enter a name of 1 to 100 characters.'; end if;
   if exists(select 1 from public.member_invitations where email=v_email and status='pending') then raise exception 'An invitation already exists. Use Resend on that invitation.'; end if;
 else
   select * into i from public.member_invitations where id=p_invitation for update;
   if not found or i.status<>'pending' then raise exception 'Only a pending or expired invitation can be resent.'; end if;
   if i.last_attempt_at>now()-interval '60 seconds' then raise exception 'Wait 60 seconds before resending this invitation.'; end if;
   v_email:=i.email;
 end if;
 select a.id into target from auth.users a where lower(a.email)=v_email;
 if target is not null and exists(select 1 from public.profiles where id=target and account_status<>'invited') then
   raise exception 'This email already belongs to a club account. Manage the existing member instead.';
 end if;
 if p_invitation is null then
   insert into public.member_invitations(email,display_name,created_by) values(v_email,trim(p_name),u) returning * into i;
 else
   update public.member_invitations set token=gen_random_uuid(),expires_at=now()+interval '7 days',sent_at=null,
     delivery_status='sending',last_attempt_at=now() where id=i.id returning * into i;
 end if;
 insert into public.member_management_events(actor_id,event_type,reason,details)
 values(u,case when p_invitation is null then 'invited' else 'invitation_resent' end,'Member invitation requested.',jsonb_build_object('email',v_email,'invitation',i.id));
 return jsonb_build_object('id',i.id,'token',i.token,'email',v_email,'display_name',i.display_name,'existing_user',target);
end; $$;

-- Server-only delivery bookkeeping; failures remain visible and retryable.
create function public.ml_invitation_delivery(p_id uuid,p_token uuid,p_actor uuid,p_success boolean) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform pg_advisory_xact_lock(714014);
 update public.member_invitations set delivery_status=case when p_success then 'sent' else 'failed' end,
   sent_at=case when p_success then now() else null end
 where id=p_id and token=p_token and status='pending';
 if not found then raise exception 'Invitation changed. Refresh the Members page.'; end if;
 insert into public.member_management_events(actor_id,event_type,reason,details)
 values(p_actor,case when p_success then 'invitation_sent' else 'invitation_delivery_failed' end,
   case when p_success then 'Invitation email accepted by the mail service.' else 'Email delivery failed. Resend is available.' end,jsonb_build_object('invitation',p_id));
end; $$;

create function public.ml_revoke_invitation(p_id uuid,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid;
begin
 perform pg_advisory_xact_lock(714014); u:=public.ml_require_president();
 if p_reason is null or length(trim(p_reason)) not between 3 and 500 then raise exception 'Enter a reason of 3 to 500 characters.'; end if;
 update public.member_invitations set status='revoked',token=gen_random_uuid() where id=p_id and status='pending';
 if not found then raise exception 'This invitation is no longer pending.'; end if;
 insert into public.member_management_events(actor_id,event_type,reason,details) values(u,'invitation_revoked',trim(p_reason),jsonb_build_object('invitation',p_id));
end; $$;

-- A verified Auth session AND the latest app invitation token are required.
-- No browser RPC can activate itself or choose a role.
create function public.ml_validate_invitation(p_user uuid,p_token uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare result uuid;
begin
 select i.id into result from public.member_invitations i join auth.users a on lower(a.email)=i.email
 join public.profiles p on p.id=a.id
 where a.id=p_user and p.account_status='invited' and i.token=p_token and i.status='pending'
   and i.expires_at>now() and i.sent_at is not null and i.delivery_status='sent';
 if result is null then raise exception 'Invitation is expired, revoked, replaced, or belongs to another email. Ask the President to resend it.'; end if;
 return result;
end; $$;
create function public.ml_activate_member(p_user uuid,p_token uuid) returns void
language plpgsql security definer set search_path='' as $$
declare invite_id uuid; i public.member_invitations;
begin
 perform pg_advisory_xact_lock(714014);
 invite_id:=public.ml_validate_invitation(p_user,p_token);
 select * into i from public.member_invitations where id=invite_id for update;
 update public.profiles set account_status='active',role='member',display_name=i.display_name where id=p_user;
 update public.member_invitations set status='accepted',accepted_by=p_user,accepted_at=now() where id=i.id;
 insert into public.member_management_events(actor_id,target_id,event_type,reason,details)
 values(p_user,p_user,'invitation_accepted','Member set their own password and joined.',jsonb_build_object('invitation',i.id));
end; $$;

create function public.ml_handover_status() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare u uuid:=public.ml_require_user();
begin
 return (select jsonb_build_object('id',h.id,'from_id',h.from_id,'to_id',h.to_id,'from_name',a.display_name,
   'to_name',b.display_name,'reason',h.reason,'expires_at',h.expires_at)
   from public.president_handovers h join public.profiles a on a.id=h.from_id join public.profiles b on b.id=h.to_id
   where h.status='pending' and h.expires_at>now() and u in (h.from_id,h.to_id));
end; $$;
create function public.ml_start_handover(p_user uuid,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid;
begin
 perform pg_advisory_xact_lock(714014); u:=public.ml_require_president();
 if p_reason is null or length(trim(p_reason)) not between 3 and 500 then raise exception 'Enter a reason of 3 to 500 characters.'; end if;
 if u=p_user or not exists(select 1 from public.profiles where id=p_user and account_status='active' and role in ('member','treasurer')) then raise exception 'Select another active Member or Treasurer.'; end if;
 update public.president_handovers set status='cancelled',resolved_at=now() where status='pending' and expires_at<=now();
 if exists(select 1 from public.president_handovers where status='pending') then raise exception 'Resolve the existing President handover first.'; end if;
 insert into public.president_handovers(from_id,to_id,reason) values(u,p_user,trim(p_reason));
 insert into public.member_management_events(actor_id,target_id,event_type,reason) values(u,p_user,'handover_started',trim(p_reason));
end; $$;
create function public.ml_resolve_handover(p_id uuid,p_action text,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid; h public.president_handovers;
begin
 perform pg_advisory_xact_lock(714014); u:=public.ml_require_user();
 if p_reason is null or length(trim(p_reason)) not between 3 and 500 then raise exception 'Enter a reason of 3 to 500 characters.'; end if;
 select * into h from public.president_handovers where id=p_id for update;
 if not found or h.status<>'pending' or h.expires_at<=now() then raise exception 'This handover is no longer pending or has expired.'; end if;
 if p_action='accept' then
   if u<>h.to_id then raise exception 'Only the nominated member can accept this handover.'; end if;
   if not exists(select 1 from public.profiles where id=h.from_id and role='president' and account_status='active') then raise exception 'The current President is no longer eligible.'; end if;
   if not exists(select 1 from public.profiles where id=u and role in ('member','treasurer') and account_status='active') then raise exception 'The nominated member is no longer eligible.'; end if;
   update public.profiles set role='president' where id=u;
   update public.profiles set role='member' where id=h.from_id;
 elsif p_action='cancel' then
   if u<>h.from_id then raise exception 'Only the initiating President can cancel this handover.'; end if;
 elsif p_action='decline' then
   if u<>h.to_id then raise exception 'Only the nominated member can decline this handover.'; end if;
 else raise exception 'Invalid handover action.';
 end if;
 update public.president_handovers set status=case p_action when 'accept' then 'accepted' when 'cancel' then 'cancelled' else 'declined' end,resolved_at=now() where id=h.id;
 insert into public.member_management_events(actor_id,target_id,event_type,reason,details)
 values(u,case when u=h.from_id then h.to_id else h.from_id end,'handover_'||p_action,trim(p_reason),jsonb_build_object('from',h.from_id,'to',h.to_id));
end; $$;

-- Server operations must also recheck account status after their initial RLS reads.
alter function public.ml_begin_ai_check(uuid,uuid,text,text) rename to ml_begin_ai_check_before_membership;
alter function public.ml_begin_receipt_read(uuid,uuid,text) rename to ml_begin_receipt_read_before_membership;
alter function public.ml_finish_receipt_claim(uuid,uuid,jsonb,jsonb,jsonb,integer) rename to ml_finish_receipt_claim_before_membership;
revoke all on function public.ml_begin_ai_check_before_membership(uuid,uuid,text,text),public.ml_begin_receipt_read_before_membership(uuid,uuid,text),public.ml_finish_receipt_claim_before_membership(uuid,uuid,jsonb,jsonb,jsonb,integer) from public,anon,authenticated,service_role;
create function public.ml_begin_ai_check(p_user uuid,p_claim uuid,p_signature text,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
begin
 if not public.ml_account_active(p_user) then raise exception 'Account is not active.'; end if;
 return public.ml_begin_ai_check_before_membership(p_user,p_claim,p_signature,p_model);
end; $$;
create function public.ml_begin_receipt_read(p_user uuid,p_session uuid,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
begin
 if not public.ml_account_active(p_user) then raise exception 'Account is not active.'; end if;
 return public.ml_begin_receipt_read_before_membership(p_user,p_session,p_model);
end; $$;
create function public.ml_finish_receipt_claim(p_user uuid,p_session uuid,p_selection jsonb,p_calculation jsonb,p_fields jsonb,p_revision integer) returns uuid
language plpgsql security definer set search_path='' as $$
begin
 if not public.ml_account_active(p_user) then raise exception 'Account is not active.'; end if;
 return public.ml_finish_receipt_claim_before_membership(p_user,p_session,p_selection,p_calculation,p_fields,p_revision);
end; $$;

revoke all on function public.ml_account_active(uuid),public.ml_require_president(),public.ml_members(),public.ml_change_member(uuid,text,text),
 public.ml_prepare_invitation(text,text,uuid),public.ml_invitation_delivery(uuid,uuid,uuid,boolean),public.ml_revoke_invitation(uuid,text),
 public.ml_validate_invitation(uuid,uuid),public.ml_activate_member(uuid,uuid),public.ml_handover_status(),public.ml_start_handover(uuid,text),
 public.ml_resolve_handover(uuid,text,text),public.ml_begin_ai_check(uuid,uuid,text,text),public.ml_begin_receipt_read(uuid,uuid,text),
 public.ml_finish_receipt_claim(uuid,uuid,jsonb,jsonb,jsonb,integer) from public,anon,authenticated;
grant execute on function public.ml_account_active(uuid),public.ml_members(),public.ml_change_member(uuid,text,text),
 public.ml_prepare_invitation(text,text,uuid),public.ml_revoke_invitation(uuid,text),public.ml_handover_status(),
 public.ml_start_handover(uuid,text),public.ml_resolve_handover(uuid,text,text) to authenticated;
grant execute on function public.ml_invitation_delivery(uuid,uuid,uuid,boolean),public.ml_validate_invitation(uuid,uuid),public.ml_activate_member(uuid,uuid),
 public.ml_begin_ai_check(uuid,uuid,text,text),public.ml_begin_receipt_read(uuid,uuid,text),public.ml_finish_receipt_claim(uuid,uuid,jsonb,jsonb,jsonb,integer) to service_role;
notify pgrst,'reload schema';
commit;

-- Migration: 015_ai_usage_limit.sql
-- Run after 014. Raises the shared rolling AI allowance from 20 to 100 per user.
-- Keeps membership wrappers, private function permissions and the 30-second cooldown.
begin;
do $$ begin
 if to_regprocedure('public.ml_begin_ai_check_before_membership(uuid,uuid,text,text)') is null
 or to_regprocedure('public.ml_begin_receipt_read_before_membership(uuid,uuid,text)') is null then
  raise exception 'Apply migration 014_member_management.sql before migration 015.';
 end if;
end; $$;

create or replace function public.ml_begin_ai_check_before_membership(p_user uuid,p_claim uuid,p_signature text,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
declare c public.claims; rid uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('moneylai-ai-user-'||p_user::text,0));
 select * into c from public.claims where id=p_claim for update;
 if not found or not (c.claimant_id=p_user or exists(select 1 from public.profiles where id=p_user and role='treasurer')) then
  raise exception 'Claim access denied.';
 end if;
 if c.status not in ('draft','submitted','needs_info','rejected') then raise exception 'AI checks are available before approval.'; end if;
 if exists(select 1 from public.ai_claim_checks where claim_id=p_claim and status='running' and created_at>now()-interval '3 minutes') then
  raise exception 'A check is already running. Please wait a few minutes.';
 end if;
 if exists(select 1 from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '30 seconds') then
  raise exception 'Please wait 30 seconds before another check.';
 end if;
 if (select count(*) from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '24 hours')>=100 then
  raise exception 'Daily AI check limit reached (100 checks per user in the past 24 hours).';
 end if;
 update public.ai_claim_checks set status='failed',finished_at=now() where claim_id=p_claim and status='running';
 insert into public.ai_claim_checks(claim_id,requested_by,input_signature,model) values(p_claim,p_user,p_signature,p_model) returning id into rid;
 return rid;
end; $$;

create or replace function public.ml_begin_receipt_read_before_membership(p_user uuid,p_session uuid,p_model text) returns uuid
language plpgsql security definer set search_path='' as $$
declare s public.receipt_drafts; rid uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('moneylai-ai-user-'||p_user::text,0));
 select * into s from public.receipt_drafts where id=p_session for update;
 if not found or s.user_id<>p_user or s.claim_id is not null or s.expires_at<=now() then raise exception 'Receipt draft is unavailable or expired.'; end if;
 if s.status='complete' then raise exception 'Receipt is already read. Use its saved extraction.'; end if;
 if s.status='running' and exists(select 1 from public.ai_claim_checks where id=s.run_id and created_at>now()-interval '3 minutes') then raise exception 'A receipt reading is already running.'; end if;
 if exists(select 1 from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '30 seconds') then raise exception 'Please wait 30 seconds before another AI request.'; end if;
 if (select count(*) from public.ai_claim_checks where requested_by=p_user and created_at>now()-interval '24 hours')>=100 then raise exception 'Daily AI check limit reached (100 checks per user in the past 24 hours).'; end if;
 insert into public.ai_claim_checks(requested_by,input_signature,model) values(p_user,'receipt:'||s.id::text,p_model) returning id into rid;
 update public.receipt_drafts set status='running',run_id=rid,model=p_model where id=s.id;
 return rid;
end; $$;

revoke all on function public.ml_begin_ai_check_before_membership(uuid,uuid,text,text),
 public.ml_begin_receipt_read_before_membership(uuid,uuid,text) from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;

-- Migration: 016_google_membership.sql
-- Existing deployments: apply once after 015. Existing accounts remain unchanged.
begin;
create table public.membership_applications (
 user_id uuid primary key references public.profiles(id),
 status text not null default 'pending' check(status in ('pending','approved','rejected','completed')),
 created_at timestamptz not null default now(),
 reviewed_at timestamptz,
 reviewed_by uuid references public.profiles(id),
 reason text,
 completed_at timestamptz
);
alter table public.membership_applications enable row level security;
revoke all on public.membership_applications from anon,authenticated;

-- Read-only status is separate from explicitly submitting an application.
create function public.ml_membership_status() returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('status',a.status,'reason',a.reason,'created_at',a.created_at)
 from public.membership_applications a where a.user_id=auth.uid();
$$;
create function public.ml_request_membership() returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();
begin
 perform 1 from public.profiles where id=u and account_status='invited' for update;
 if not found then raise exception 'Only an unactivated account can apply.'; end if;
 if not exists(select 1 from auth.identities where user_id=u and provider='google') then
   raise exception 'Verify your account with Google before applying.';
 end if;
 insert into public.membership_applications(user_id) values(u) on conflict(user_id) do nothing;
 if found then
   insert into public.member_management_events(actor_id,target_id,event_type,reason)
   values(u,u,'membership_requested','Requested club membership using Google.');
 end if;
end; $$;
create function public.ml_membership_applications() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform public.ml_require_president();
 return coalesce((select jsonb_agg(jsonb_build_object('user_id',a.user_id,'email',u.email,
   'display_name',p.display_name,'status',a.status,'created_at',a.created_at,'reason',a.reason)
   order by a.created_at) from public.membership_applications a join public.profiles p on p.id=a.user_id
   join auth.users u on u.id=a.user_id where a.status<>'completed'),'[]'::jsonb);
end; $$;
create function public.ml_review_membership(p_user uuid,p_approve boolean,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
declare actor uuid:=public.ml_require_president();
begin
 if p_approve is null or p_reason is null or length(trim(p_reason)) not between 3 and 500 then
   raise exception 'Enter a reason of 3 to 500 characters.';
 end if;
 perform 1 from public.profiles where id=p_user and account_status='invited' for update;
 if not found then raise exception 'This account is no longer awaiting activation.'; end if;
 update public.membership_applications set status=case when p_approve then 'approved' else 'rejected' end,
   reviewed_by=actor,reviewed_at=now(),reason=trim(p_reason)
 where user_id=p_user and (status='pending' or (status='rejected' and p_approve) or (status='approved' and not p_approve));
 if not found then raise exception 'Application has already changed. Refresh the list.'; end if;
 insert into public.member_management_events(actor_id,target_id,event_type,reason)
 values(actor,p_user,case when p_approve then 'membership_approved' else 'membership_rejected' end,trim(p_reason));
end; $$;
-- These two functions are server-only. Browser password updates cannot grant membership.
create function public.ml_validate_membership_activation(p_user uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.membership_applications a join public.profiles p on p.id=a.user_id
   where a.user_id=p_user and a.status='approved' and p.account_status='invited') then
   raise exception 'President approval is required before activation.';
 end if;
end; $$;
create function public.ml_complete_membership(p_user uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform 1 from public.profiles where id=p_user for update;
 perform public.ml_validate_membership_activation(p_user);
 update public.profiles set account_status='active',role='member' where id=p_user;
 update public.membership_applications set status='completed',completed_at=now() where user_id=p_user;
 insert into public.member_management_events(actor_id,target_id,event_type,reason)
 values(p_user,p_user,'membership_activated','Set a MoneyLai password after President approval.');
end; $$;
revoke all on function public.ml_membership_status(),public.ml_request_membership(),
 public.ml_membership_applications(),public.ml_review_membership(uuid,boolean,text),
 public.ml_validate_membership_activation(uuid),public.ml_complete_membership(uuid) from public,anon,authenticated;
grant execute on function public.ml_membership_status(),public.ml_request_membership(),
 public.ml_membership_applications(),public.ml_review_membership(uuid,boolean,text) to authenticated;
grant execute on function public.ml_validate_membership_activation(uuid),public.ml_complete_membership(uuid) to service_role;
commit;

-- Migration: 017_claim_email_notifications.sql
-- Transactional outbox: no historical backfill and no email/network calls in financial RPCs.
create table public.claim_email_notifications (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null unique references public.claim_events(id),
  claim_id uuid not null references public.claims(id),
  recipient_id uuid not null references public.profiles(id),
  kind text not null check(kind in ('approved','paid')),
  payload jsonb not null,
  status text not null default 'pending' check(status in ('pending','sending','sent','cancelled')),
  attempts integer not null default 0,
  available_at timestamptz not null default now(),
  lease_token uuid,
  sent_at timestamptz,
  last_error text,
  created_at timestamptz not null default now()
);
alter table public.claim_email_notifications enable row level security;
revoke all on public.claim_email_notifications from public, anon, authenticated;
grant select on public.claim_email_notifications to service_role;
create index on public.claim_email_notifications(status,available_at);

create function public.ml_enqueue_claim_email() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.event_type in ('approved','paid') then
    insert into public.claim_email_notifications(event_id,claim_id,recipient_id,kind,payload)
    select new.id,c.id,c.claimant_id,new.event_type,
      jsonb_build_object('claim_number','ML-'||lpad(c.claim_number::text,greatest(6,length(c.claim_number::text)),'0'),'amount',c.amount,
        'activity',a.name,'paid_on',p.paid_on,'reference',p.reference)
    from public.claims c join public.activities a on a.id=c.activity_id
    left join public.payments p on p.claim_id=c.id
    where c.id=new.claim_id
    on conflict(event_id) do nothing;
  end if;
  return new;
end; $$;
create trigger claim_email_enqueue after insert on public.claim_events
for each row execute function public.ml_enqueue_claim_email();

-- Do not send a delayed "awaiting payment" email after payment or revoked approval.
create function public.ml_cancel_stale_claim_email() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.status='approved' and new.status<>'approved' then
    update public.claim_email_notifications set status='cancelled',lease_token=null
    where claim_id=new.id and kind='approved' and status in ('pending','sending');
  end if;
  return new;
end; $$;
create trigger claim_email_cancel after update of status on public.claims
for each row execute function public.ml_cancel_stale_claim_email();

-- Atomically lease one item, so concurrent requests cannot send the same pending item.
create function public.ml_take_claim_email(p_claim_id uuid default null)
returns setof public.claim_email_notifications
language sql security definer set search_path = '' as $$
  update public.claim_email_notifications n
  set status='sending',attempts=attempts+1,lease_token=gen_random_uuid(),available_at=now()+interval '10 minutes'
  where n.id=(select q.id from public.claim_email_notifications q
    where q.status in ('pending','sending') and q.available_at<=now()
      and (p_claim_id is null or q.claim_id=p_claim_id)
    order by q.created_at,q.id for update skip locked limit 1)
  returning n.*;
$$;
create function public.ml_finish_claim_email(p_id uuid,p_lease uuid,p_success boolean)
returns boolean language plpgsql security definer set search_path = '' as $$
begin
  update public.claim_email_notifications
  set status=case when p_success then 'sent' else 'pending' end,
      sent_at=case when p_success then now() else null end,
      last_error=case when p_success then null else 'Email delivery failed. Check server configuration and retry.' end,
      available_at=now()+least(3600,60*power(2,least(attempts,6))) * interval '1 second',
      lease_token=null
  where id=p_id and lease_token=p_lease and status='sending';
  return found;
end; $$;
revoke all on function public.ml_enqueue_claim_email() from public,anon,authenticated;
revoke all on function public.ml_cancel_stale_claim_email() from public,anon,authenticated;
revoke all on function public.ml_take_claim_email(uuid) from public,anon,authenticated;
revoke all on function public.ml_finish_claim_email(uuid,uuid,boolean) from public,anon,authenticated;
grant execute on function public.ml_take_claim_email(uuid),public.ml_finish_claim_email(uuid,uuid,boolean) to service_role;
